import { displayAlpha, displayPixel } from './display-values';

export const PAUSE = HUD.pause;
const exits: Record<string, keyof typeof PAUSE.out> = {
  btnSettings_mc: 'Button2Out_mc',
  btn3_mc: 'Button3Out_mc',
  btn5_mc: 'Button5Out_mc',
